using System.IdentityModel.Tokens.Jwt;using EEMS.Api.Authorization;using EEMS.Api.Events;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace EEMS.Api.Controllers;[ApiController,Route("api/v1/elections/{electionId:guid}/events")]public sealed class EventsController(EventOperationsService s):ControllerBase{[HttpGet,Authorize(Policy=PermissionCodes.EventsRead)]public async Task<ActionResult<EventWorkspace>> Get(Guid electionId,CancellationToken ct){var x=await s.Get(electionId,ct);return x is null?NotFound():Ok(x);}[HttpPost("venues"),Authorize(Policy=PermissionCodes.EventsManage)]public async Task<ActionResult<VenueSummary>> AddVenue(Guid electionId,VenueRequest r,CancellationToken ct){var x=await s.AddVenue(r.AreaId,r.Name,r.Address,r.Capacity,ct);return x is null?BadRequest():Ok(x);}[HttpPost,Authorize(Policy=PermissionCodes.EventsManage)]public async Task<ActionResult<EventSummary>> AddEvent(Guid electionId,EventRequest r,CancellationToken ct){var x=await s.AddEvent(electionId,new(r.EventTypeId,r.StateId,r.AreaId,r.VenueId,r.Title,r.StartsAtUtc,r.EndsAtUtc),ct);return x is null?BadRequest():Ok(x);}[HttpPut("{eventId:guid}/complete"),Authorize(Policy=PermissionCodes.EventsManage)]public async Task<ActionResult<EventSummary>> Complete(Guid electionId,Guid eventId,CompleteEventRequest r,CancellationToken ct){var x=await s.Complete(electionId,eventId,r.ExpectedVersion,r.Report,ct);return x is null?Conflict():Ok(x);}[HttpPost("meetings"),Authorize(Policy=PermissionCodes.EventsManage)]public async Task<ActionResult<MeetingSummary>> AddMeeting(Guid electionId,MeetingRequest r,CancellationToken ct){if(!UserId(out var u))return Unauthorized();var x=await s.AddMeeting(electionId,u,new(r.EventId,r.Title,r.Agenda,r.StartsAtUtc,r.EndsAtUtc),ct);return x is null?BadRequest():Ok(x);}[HttpPost("meetings/{meetingId:guid}/participants/{userId:guid}"),Authorize(Policy=PermissionCodes.EventsManage)]public async Task<IActionResult>AddParticipant(Guid electionId,Guid meetingId,Guid userId,CancellationToken ct)=>await s.AddParticipant(electionId,meetingId,userId,ct)?NoContent():BadRequest();[HttpPut("meetings/{meetingId:guid}/participants/{userId:guid}/attendance"),Authorize(Policy=PermissionCodes.EventsManage)]public async Task<IActionResult>Attend(Guid electionId,Guid meetingId,Guid userId,CancellationToken ct)=>await s.Attend(electionId,meetingId,userId,ct)?NoContent():NotFound();private bool UserId(out Guid x)=>Guid.TryParse(User.FindFirst(JwtRegisteredClaimNames.Sub)?.Value,out x);}
public sealed record VenueRequest(long AreaId,string Name,string Address,int? Capacity);public sealed record EventRequest(short EventTypeId,short StateId,long AreaId,Guid? VenueId,string Title,DateTimeOffset StartsAtUtc,DateTimeOffset EndsAtUtc);public sealed record CompleteEventRequest(int ExpectedVersion,string Report);public sealed record MeetingRequest(Guid? EventId,string Title,string Agenda,DateTimeOffset StartsAtUtc,DateTimeOffset EndsAtUtc);
